#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int E, M, D;
    cin >> E >> M >> D;

    vector<pair<int, int>> like(M);
    for (int i = 0; i < M; ++i) {
        cin >> like[i].first >> like[i].second;
    }

    vector<pair<int, int>> dislike(D);
    for (int i = 0; i < D; ++i) {
        cin >> dislike[i].first >> dislike[i].second;
    }

    vector<int> group(E + 1, 0);

    int G = E / 3;
    for (int g = 1; g <= G; ++g) {
        int a, b, c;
        cin >> a >> b >> c;
        group[a] = group[b] = group[c] = g;
    }

    long long answer = 0;

    for (auto [x, y] : like) {
        if (group[x] != group[y]) {
            ++answer;
        }
    }

    for (auto [x, y] : dislike) {
        if (group[x] == group[y]) {
            ++answer;
        }
    }

    cout << answer << '\n';

    return 0;
}
